if($_SERVER['REQUEST_METHOD']==='POST')task('du_lieu.php',function(PDO $db,array $u)use($sets){if($u['vai_tro']!=='SO')throw new RuntimeException('Chỉ tài khoản Sở được nhập dữ liệu nền trong bộ mẫu này.');$table=val('table');if(!isset($sets[$table]))throw new RuntimeException('Bảng không hợp lệ.');$keys=array_keys($sets[$table][1]);$values=[];foreach($keys as $key){$v=val($key);$values[]=($v===''&&in_array($key,['ma_truong','nguyen_vong_trung_tuyen'],true)&&$table==='ket_qua_xet_tuyen')?null:required_val($key);}
