 $columns=implode(',',array_map(fn($c)=>'`'.$c.'`',$keys));$placeholders=implode(',',array_fill(0,count($keys),'?'));$q=$db->prepare('INSERT INTO `'.$table.'`('.$columns.') VALUES('.$placeholders.')');$q->execute($values);audit($db,$u['id'],'NHAP_DU_LIEU',$table.' / '.implode(' - ',$values));});
