$selected=(string)($_GET['table']??'truong_thpt');if(!isset($sets[$selected]))$selected='truong_thpt';echo '<div class="panel"><h2>Chọn bảng muốn nhập</h2><div class="flow">';foreach($sets as $key=>[$label])echo '<a class="btn '.($selected===$key?'':'secondary').'" href="du_lieu.php?table='.urlencode($key).'">'.esc($label).'</a>';echo '</div></div><div class="panel"><h2>'.esc($sets[$selected][0]).'</h2>';form_open();echo '<input type="hidden" name="table" value="'.esc($selected).'">';foreach($sets[$selected][1] as $key=>$label){$isnumber=in_array($key,['kha_nang_tiep_nhan','nam_tuyen_sinh','ho_so_hop_le','suc_chua','thu_tu','da_xac_nhan','nguyen_vong_trung_tuyen','tong_diem'],true);$optional=$selected==='ket_qua_xet_tuyen'&&in_array($key,['ma_truong','nguyen_vong_trung_tuyen'],true);field($key,$label,$isnumber?'number':'text',!$optional,$isnumber?'step="any"':'');}form_close('Thêm bản ghi');echo '</div><div class="panel"><h2>Dữ liệu hiện có: '.esc($sets[$selected][0]).'</h2>';$rows=db()->query('SELECT * FROM `'.$selected.'` ORDER BY 1 DESC LIMIT 50')->fetchAll();if($selected==='bai_thi'){echo '<div class="note">Bảng bài thi chứa ánh xạ nhạy cảm mã phách–thí sinh. Chỉ xem trong tài khoản Sở; không cung cấp cho cán bộ chấm thi.</div>';}if($rows)table_rows($rows,array_keys($rows[0]));else echo '<div class="empty">Chưa có dữ liệu.</div>';echo '</div>';page_end();
